/**
 * MILO frame data and timing. The pixels live in art.ts, generated by tools/bake-art.mjs from the approved v4 CRT head:
 * a 32×32 base frame (steady eyes, flat mouth, status light on) plus small patches for eyes, mouth and the
 * headband status light, and a hand-simplified 16×16 head for xs. Patches touch disjoint regions, so any
 * eye / mouth / light combination composes cleanly.
 */
import { HEAD, HEAD_PATCHES, MINI, MINI_ALERT, PALETTE, TONES } from './art';
import type { Eye, Light, MiloState, MiloStyleId, Mouth, Palette, Patch } from './types';

export type { Eye, Light, MiloState, MiloStyleId, Mouth, Palette, Patch } from './types';

export interface MiloArt {
  base: string[];
  eyes: Record<Eye, Patch>;
  mouths: Record<Mouth, Patch>;
  lights: Record<Light, Patch>;
}

export interface MiloStyle {
  id: MiloStyleId;
  name: string;
  blurb: string;
  art: MiloArt;
  /** 16×16 head used at size "xs". */
  mini: MiloArt;
  palette: Palette;
  wave: { bar: string; lead: string };
}

const NONE: Patch = [];

const HEAD_ART: MiloArt = {
  base: HEAD,
  eyes: { open: NONE, ...HEAD_PATCHES.eyes },
  mouths: { rest: NONE, ...HEAD_PATCHES.mouths },
  lights: { on: NONE, ...HEAD_PATCHES.lights },
};

const MINI_ART: MiloArt = {
  base: MINI,
  eyes: { open: NONE, closed: NONE, aside: NONE, wide: NONE },
  mouths: { rest: NONE, open: NONE, mid: NONE, aside: NONE },
  lights: { on: NONE, dim: NONE, alert: MINI_ALERT },
};

/** Calm, desaturated ramps; the R* tones (alert only) are the one saturated colour. */
export const PALETTE_COLOR: Palette = PALETTE;

/** Single-ink HUD version: light values print, dark values drop out; alert red stays red. */
export const PALETTE_MONO: Palette = Object.fromEntries(
  Object.entries(TONES).flatMap(([key, tone]) => {
    if (tone[0] === 'R' || tone === 'lR') return [[key, PALETTE[key]]];
    const dark = tone === 'K' || tone === 'O0' || tone === 'P1' || tone === 'P0' || 'lDCE'.includes(tone[0]);
    if (dark) return [];
    return [[key, tone === 'G1' || tone === 'G2' ? '#e3eff2' : '#a9bfc7']];
  }),
);

export const STYLES: Record<MiloStyleId, MiloStyle> = {
  crt: { id: 'crt', name: 'CRT', blurb: 'Monitor head, dark glass, steady eyes, headband status light.', art: HEAD_ART, mini: MINI_ART, palette: PALETTE_COLOR, wave: { bar: '#66828d', lead: '#c98b5e' } },
  mono: { id: 'mono', name: 'Mono', blurb: 'Single-ink HUD rendering of the same head.', art: HEAD_ART, mini: MINI_ART, palette: PALETTE_MONO, wave: { bar: '#66828d', lead: '#a9bfc7' } },
};
export const RECOMMENDED_STYLE: MiloStyleId = 'crt';

export const EXPRESSIONS: Record<MiloState, { eyes: Eye; mouth: Mouth; light: Light }> = {
  idle: { eyes: 'open', mouth: 'rest', light: 'on' },
  speaking: { eyes: 'open', mouth: 'rest', light: 'on' },
  thinking: { eyes: 'aside', mouth: 'aside', light: 'dim' },
  alert: { eyes: 'wide', mouth: 'rest', light: 'alert' },
};

export const STATUS_LABEL: Record<MiloState, string> = {
  idle: 'ONLINE',
  speaking: 'TRANSMITTING',
  alert: 'DECISION WAITING',
  thinking: 'PROCESSING',
};

export const TIMING = {
  msPerChar: 55,
  mouthHoldMs: 110,
  blinkEveryMs: 5600,
  blinkMs: 140,
  /** Thinking: the status light pulses between dim and on at this step. */
  thinkingStepMs: 520,
};

/** Character -> mouth line. Deliberately coarse: vowels lengthen the line, other letters shorten it. */
export function viseme(ch: string | undefined): Mouth {
  if (!ch) return 'rest';
  if (/[aeiouy]/i.test(ch)) return 'open';
  if (/[a-z0-9]/i.test(ch)) return 'mid';
  return 'rest';
}

/** Waveform bar height (0-3) for a character. */
export function amplitude(ch: string | undefined, i: number): number {
  if (!ch || !/[a-z0-9]/i.test(ch)) return 0;
  if (/[aeiou]/i.test(ch)) return 2 + ((ch.charCodeAt(0) + i) % 2);
  return 1 + ((ch.charCodeAt(0) * 7 + i) % 2);
}

export interface FrameSpec {
  eyes: Eye;
  mouth: Mouth;
  light?: Light;
}

/** Stamp eye, mouth and light patches onto the base sprite. Returns rows of palette keys. */
export function composeFrame(art: MiloArt, spec: FrameSpec): string[] {
  const grid = art.base.map((row) => Array.from(row));
  const stamp = (patch: Patch) =>
    patch.forEach(([row, col, keys]) => Array.from(keys).forEach((k, i) => { if (grid[row]) grid[row][col + i] = k; }));
  stamp(art.eyes[spec.eyes]);
  stamp(art.mouths[spec.mouth]);
  stamp(art.lights[spec.light ?? 'on']);
  return grid.map((r) => r.join(''));
}

/** Waveform heights (0-3), newest sample on the right. `cursor` is the index of the character being spoken. */
export function composeWave(text: string, cursor: number, bars: number): number[] {
  return Array.from({ length: bars }, (_, c) => {
    const i = cursor - (bars - 1 - c);
    return i >= 0 && i < text.length ? amplitude(text[i], i) : 0;
  });
}
